import{_ as d,C as r,o as l,c,a6 as n,E as o,j as e,a}from"./chunks/framework.5dd0l9Wo.js";const k=JSON.parse('{"title":"Information Disclosure","description":"Error surfaces, debug pages, backup files, version control history, and how metadata becomes an exploit primitive.","frontmatter":{"title":"Information Disclosure","description":"Error surfaces, debug pages, backup files, version control history, and how metadata becomes an exploit primitive."},"headers":[],"relativePath":"information-disclosure/index.md","filePath":"information-disclosure/index.md"}'),p={name:"information-disclosure/index.md"};function u(m,t,h,f,b,g){const s=r("LabGroup"),i=r("TopicComplete");return l(),c("div",null,[t[0]||(t[0]=n('<h1 id="information-disclosure" tabindex="-1">Information Disclosure <a class="header-anchor" href="#information-disclosure" aria-label="Permalink to &quot;Information Disclosure&quot;">​</a></h1><p class="wd-section-lede">Information disclosure is rarely the final exploit. It is the map that makes the final exploit possible: a stack trace names the framework, a backup file contains the database password, and a debug page exposes the environment.</p><div class="wd-callout"><p><strong>The model.</strong> Every response is an artifact of the system that produced it. Headers, error text, timing, file listings, and leftover build artifacts all describe internal state. The vulnerability is not that the data is &quot;sensitive&quot; in the abstract — it is that the application reveals something the attacker can act on.</p></div><h2 id="where-systems-leak" tabindex="-1">Where systems leak <a class="header-anchor" href="#where-systems-leak" aria-label="Permalink to &quot;Where systems leak&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Surface</th><th>Typical leak</th><th>Why it happens</th></tr></thead><tbody><tr><td>Error messages</td><td>framework, file paths, SQL fragments</td><td>unhandled exceptions rendered to the client</td></tr><tr><td>Debug pages</td><td>environment, config, source</td><td>development middleware left enabled</td></tr><tr><td>Backup files</td><td>source, credentials</td><td>editor or deploy script writes <code>.bak</code>, <code>.old</code>, <code>.zip</code> into the web root</td></tr><tr><td>Version control</td><td>full source history</td><td><code>.git/</code> or <code>.svn/</code> deployed with the site</td></tr><tr><td>Response headers</td><td>server, language, proxy</td><td>defaults are verbose</td></tr><tr><td>Robots / sitemaps</td><td>hidden paths</td><td>intended for crawlers, readable by anyone</td></tr></tbody></table><details class="details custom-block"><summary>🔬 Under the Hood: why a stack trace is an exploit primitive</summary><p>A stack trace tells you the language, framework version, template engine, ORM, and absolute filesystem paths. That is enough to select a known CVE, choose a payload syntax, and locate writable directories. Even a generic 500 page can leak through <strong>differing error text</strong> — which is the basis of error-based SQL injection and username enumeration.</p><p>The defence is not to hide the word &quot;error&quot;; it is to make sure the client receives a constant, generic response while the detail goes to a server-side log with a correlation id.</p></details><details class="details custom-block"><summary>⚙️ Engine Variations: what each stack leaks by default</summary><ul><li><strong>Django:</strong> <code>DEBUG = True</code> renders settings, SQL, and tracebacks; <code>ALLOWED_HOSTS</code> errors reveal hostnames.</li><li><strong>Spring Boot:</strong> the Whitelabel error page can include exception class names; Actuator endpoints expose env, beans, and heap dumps.</li><li><strong>PHP:</strong> <code>display_errors = On</code> prints paths and arguments; <code>phpinfo()</code> is a full configuration dump.</li><li><strong>Node/Express:</strong> the default error handler includes the stack in development.</li><li><strong>Rails:</strong> development error pages include source excerpts and environment variables.</li></ul></details><h2 id="error-messages-and-debug-surfaces" tabindex="-1">Error messages and debug surfaces <a class="header-anchor" href="#error-messages-and-debug-surfaces" aria-label="Permalink to &quot;Error messages and debug surfaces&quot;">​</a></h2><p>Start by sending malformed input to every endpoint. A different status code, a longer body, or a framework name is a lead. Then look for known debug paths: <code>/debug</code>, <code>/actuator</code>, <code>/server-status</code>, <code>/.env</code>, <code>/phpinfo.php</code>.</p>',9)),o(s,{ids:"information-disclosure-lab-infoleak-in-error-messages, information-disclosure-lab-infoleak-on-debug-page"}),t[1]||(t[1]=e("h2",{id:"backup-files-and-source-disclosure",tabindex:"-1"},[a("Backup files and source disclosure "),e("a",{class:"header-anchor",href:"#backup-files-and-source-disclosure","aria-label":'Permalink to "Backup files and source disclosure"'},"​")],-1)),t[2]||(t[2]=e("p",null,[a("Deployment tools and editors create siblings: "),e("code",null,"index.php.bak"),a(", "),e("code",null,"app.js.old"),a(", "),e("code",null,"backup.zip"),a(", "),e("code",null,"~index.php"),a(". Directory listing is not required; guess the name from the live file. Source code often contains hardcoded credentials, API keys, and the exact validation logic you need to bypass.")],-1)),o(s,{ids:"information-disclosure-lab-infoleak-via-backup-files, information-disclosure-lab-infoleak-authentication-bypass"}),t[3]||(t[3]=n(`<h2 id="version-control-history" tabindex="-1">Version control history <a class="header-anchor" href="#version-control-history" aria-label="Permalink to &quot;Version control history&quot;">​</a></h2><p>A deployed <code>.git</code> directory is a complete repository. <code>/.git/HEAD</code> confirms it; <code>/.git/config</code> names the remote; the object database contains every committed secret, including ones deleted from the working tree.</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /.git/HEAD          → ref: refs/heads/master</span></span>
<span class="line"><span>GET /.git/config        → remote origin, sometimes credentials</span></span>
<span class="line"><span>git-dumper URL ./repo   → reconstruct working tree + history</span></span>
<span class="line"><span>git log -p              → find secrets removed in later commits</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div>`,3)),o(s,{ids:"information-disclosure-lab-infoleak-in-version-control-history"}),t[4]||(t[4]=e("details",{class:"details custom-block"},[e("summary",null,"🔬 Under the Hood: why deleted secrets stay in Git"),e("p",null,[a("Git stores content-addressed objects. A commit references a tree, which references blobs. Deleting a file in a later commit creates a new tree; the old blob remains reachable from the old commit until garbage collection, and the reflog or any clone keeps it alive. Rotating the credential is the only real remediation — removing the file from "),e("code",null,"HEAD"),a(" does not remove it from history.")])],-1)),t[5]||(t[5]=e("div",{class:"wd-callout wd-callout--warn"},[e("p",null,[e("strong",null,"Defence."),a(" Return generic errors with a correlation id, disable debug middleware in production, block dotfiles and backup extensions at the web server, never deploy VCS metadata, and treat every secret that ever entered a repository as compromised.")])],-1)),o(i,{"topic-id":"information-disclosure",label:"Mark information disclosure complete"})])}const v=d(p,[["render",u]]);export{k as __pageData,v as default};
